INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_bio_pod_b001_003', 'topic_biochemistry', 'subj_nsmq_biology', 'exam_nsmq', NULL, NULL, 'A DNA molecule contains 30% guanine. What percentage of its bases are adenine?', 'problem', 'problem_of_day', NULL, '20%', 'By Chargaff’s base-pairing rules G = C, so cytosine is also 30% and G + C = 60%. The remaining 40% is shared equally between A and T because A = T, giving adenine = 20%.', 'medium', '5', '1', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL);
